from contextlib import asynccontextmanager
from langchain_mcp_adapters.client import MultiServerMCPClient

@asynccontextmanager
async def lifespan(app: FastAPI):
    print('hello')
    global tool_map

    client = MultiServerMCPClient(
        {
            "demo": {
                "command": "python",
                "args": ["gmail_service_mcp.py"],
                "transport": "stdio",
            }
        }
    )

    tools = await client.get_tools()

    tool_map = {t.name: t for t in tools}

    print("Loaded MCP Tools:")
    print(tool_map.keys())

    yield

app = FastAPI(
    title="AI Email Assistant",
    lifespan=lifespan
)

initialize_db()
print("db initialized")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

class MeetingRequest(BaseModel):
    thread_id:str
    subject: str
    meeting_date: str
    meeting_time: str
    attendees: List[str]

class ReplyRequest(BaseModel):
    to_email: str
    subject: str
    body_text: str
    thread_id: str 

@app.get("/health")
def health():
    """Health check endpoint."""
    return {"status": "healthy"}

@app.get("/emails")
def fetch_all_emails():
    try:
        emails = get_all_emails()
        return {
            "status": "success",
            "emails": emails
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/emails/{thread_id}")
def fetch_email(thread_id: str):
    try:
        email = get_email_by_id(thread_id)

        if not email:
            raise HTTPException(
                status_code=404,
                detail="Email not found"
            )

        return {
            "status": "success",
            "email": email
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/emails/{thread_id}/actions")
def fetch_actions(thread_id: str):
    try:

        actions = get_actions_by_email(thread_id)

        return {
            "status": "success",
            "actions": actions
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

