@app.post("/schedule-meeting")
async def schedule_meeting(data: MeetingRequest):
    try:

        meeting_tool = tool_map["create_meeting"]

        meeting_result = await meeting_tool.ainvoke(
            {
                "thread_id": data.thread_id,
                "subject": data.subject,
                "meeting_date": data.meeting_date,
                "meeting_time": data.meeting_time,
                "attendees": data.attendees
            }
        )

        meet_link = meeting_result["meet_link"]

        save_action(
            thread_id=data.thread_id,
            action_type="meeting_scheduled",
            action_value=meet_link
        )

        return {
            "status": "success",
            "meet_link": meet_link
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
        
